"use client"

import animation from "react-useanimations/lib/arrowLeft"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Arrow Left" from https://useanimations.com (MIT): https://useanimations.com/icons/arrow-left
export function AnimatedArrowLeft(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover-replay"
      {...props}
    />
  )
}
